create table public.gears (
  id bigint generated by default as identity primary key,
  owner_id uuid references auth.users (id) default auth.uid(),
  name text not null check (length(trim(name)) > 0),
  category text not null check (category in ('KAMERA', 'LENSA', 'AUDIO', 'LIGHTING')),
  price_per_day integer not null check (price_per_day > 0),
  rating double precision not null default 0,
  review_count integer not null default 0,
  distance_km double precision not null default 0,
  owner_name text not null,
  location text not null,
  description text[] not null default '{}',
  specs text[] not null default '{}',
  included text[] not null default '{}',
  available_from date not null,
  available_until date not null check (available_until >= available_from),
  images text[] not null default '{}',
  created_at timestamptz not null default now()
);

create table public.bookings (
  id bigint generated by default as identity primary key,
  gear_id bigint not null references public.gears (id) on delete cascade,
  start_date date not null,
  end_date date not null check (end_date >= start_date)
);

create table public.rentals (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  gear_id bigint not null references public.gears (id) on delete cascade,
  pickup_date date not null,
  return_date date not null check (return_date > pickup_date),
  payment_method_id integer not null,
  created_at timestamptz not null default now()
);

create index on public.bookings (gear_id);
create index on public.rentals (user_id);

alter table public.gears enable row level security;
alter table public.bookings enable row level security;
alter table public.rentals enable row level security;

create policy "gears are public" on public.gears for select using (true);
create policy "signed-in users list gear" on public.gears for insert to authenticated
  with check (owner_id = auth.uid());

create policy "bookings are public" on public.bookings for select using (true);

create policy "users read own rentals" on public.rentals for select to authenticated
  using (user_id = auth.uid());
create policy "users create own rentals" on public.rentals for insert to authenticated
  with check (user_id = auth.uid());

-- A rental blocks the gear's calendar for everyone, while the rental row itself stays private.
create function public.book_rental() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (
    select 1 from public.bookings b
    where b.gear_id = new.gear_id
      and b.start_date <= new.return_date
      and b.end_date >= new.pickup_date
  ) then
    raise exception 'Gear sudah dibooking pada tanggal tersebut';
  end if;
  insert into public.bookings (gear_id, start_date, end_date)
  values (new.gear_id, new.pickup_date, new.return_date);
  return new;
end;
$$;

create trigger rentals_book after insert on public.rentals
  for each row execute function public.book_rental();

